WITH RECURSIVE imported_slots(reservation_id,court_id,slot_at,ends_at) AS (
  SELECT id,court_id,starts_at,ends_at FROM reservations WHERE id LIKE 'turnero-%'
  UNION ALL
  SELECT reservation_id,court_id,strftime('%Y-%m-%dT%H:%M:%fZ',datetime(slot_at,'+30 minutes')),ends_at
  FROM imported_slots WHERE datetime(slot_at,'+30 minutes') < datetime(ends_at)
)
INSERT OR IGNORE INTO reservation_slots (id,reservation_id,court_id,slot_at)
SELECT 'slot-' || reservation_id || '-' || replace(replace(replace(slot_at,':',''),'-',''),'T',''),reservation_id,court_id,slot_at FROM imported_slots;
